questionvariables.text:
plist: [["AG","ABCD","AC",["BD","AG","CG","AB","AC"],[["AG","AG is the line itself. Its projection lies in the base ABCD: drop a perpendicular from each end."],["CG","CG is a perpendicular from the line to the base ABCD. It joins the line to its projection; the projection is the line in the plane, AC."],["BD","BD lies in the base ABCD, but it does not join the feet of the perpendiculars from A and G."],["AB","AB lies in the base ABCD, but a perpendicular from the far end of AG lands at the other end of AC, not at the end of AB."]],14,6,11],["AG","BCGF","BG",["AG","CF","BC","BG","AB"],[["AG","AG is the line itself. Its projection lies in the face BCGF: drop a perpendicular from each end."],["AB","AB is a perpendicular from the line to the face BCGF. It joins the line to its projection; the projection is the line in the plane, BG."],["CF","CF lies in the face BCGF, but it does not join the feet of the perpendiculars from A and G."],["BC","BC lies in the face BCGF, but a perpendicular from the far end of AG lands at the other end of BG, not at the end of BC."]],6,15,3],["HB","ABCD","BD",["AC","HB","AB","DH","BD"],[["HB","HB is the line itself. Its projection lies in the base ABCD: drop a perpendicular from each end."],["DH","DH is a perpendicular from the line to the base ABCD. It joins the line to its projection; the projection is the line in the plane, BD."],["AC","AC lies in the base ABCD, but it does not join the feet of the perpendiculars from H and B."],["AB","AB lies in the base ABCD, but a perpendicular from the far end of HB lands at the other end of BD, not at the end of AB."]],9,3,11],["EC","ABFE","BE",["EC","BE","AF","EF","BC"],[["EC","EC is the line itself. Its projection lies in the face ABFE: drop a perpendicular from each end."],["BC","BC is a perpendicular from the line to the face ABFE. It joins the line to its projection; the projection is the line in the plane, BE."],["AF","AF lies in the face ABFE, but it does not join the feet of the perpendiculars from E and C."],["EF","EF lies in the face ABFE, but a perpendicular from the far end of EC lands at the other end of BE, not at the end of EF."]],6,13,12],["CE","ADHE","DE",["CD","AH","DE","AD","CE"],[["CE","CE is the line itself. Its projection lies in the face ADHE: drop a perpendicular from each end."],["CD","CD is a perpendicular from the line to the face ADHE. It joins the line to its projection; the projection is the line in the plane, DE."],["AH","AH lies in the face ADHE, but it does not join the feet of the perpendiculars from C and E."],["AD","AD lies in the face ADHE, but a perpendicular from the far end of CE lands at the other end of DE, not at the end of AD."]],5,4,8],["GA","EFGH","EG",["FH","EG","EF","GA","AE"],[["GA","GA is the line itself. Its projection lies in the top EFGH: drop a perpendicular from each end."],["AE","AE is a perpendicular from the line to the top EFGH. It joins the line to its projection; the projection is the line in the plane, EG."],["FH","FH lies in the top EFGH, but it does not join the feet of the perpendiculars from G and A."],["EF","EF lies in the top EFGH, but a perpendicular from the far end of GA lands at the other end of EG, not at the end of EF."]],16,15,7],["DF","DCGH","DG",["DF","FG","DG","CH","DC"],[["DF","DF is the line itself. Its projection lies in the face DCGH: drop a perpendicular from each end."],["FG","FG is a perpendicular from the line to the face DCGH. It joins the line to its projection; the projection is the line in the plane, DG."],["CH","CH lies in the face DCGH, but it does not join the feet of the perpendiculars from D and F."],["DC","DC lies in the face DCGH, but a perpendicular from the far end of DF lands at the other end of DG, not at the end of DC."]],20,7,6],["AF","ABCD","AB",["AF","BC","AC","AB","BF"],[["AF","AF is the line itself. Its projection lies in the base ABCD: drop a perpendicular from each end."],["BF","BF is a perpendicular from the line to the base ABCD. It joins the line to its projection; the projection is the line in the plane, AB."],["AC","AC lies in the base ABCD, but it does not join the feet of the perpendiculars from A and F."],["BC","BC lies in the base ABCD, but a perpendicular from the far end of AF lands at the other end of AB, not at the end of BC."]],5,6,12],["CH","ABCD","CD",["DH","CH","AD","CD","BD"],[["CH","CH is the line itself. Its projection lies in the base ABCD: drop a perpendicular from each end."],["DH","DH is a perpendicular from the line to the base ABCD. It joins the line to its projection; the projection is the line in the plane, CD."],["BD","BD lies in the base ABCD, but it does not join the feet of the perpendiculars from C and H."],["AD","AD lies in the base ABCD, but a perpendicular from the far end of CH lands at the other end of CD, not at the end of AD."]],18,9,10],["BH","ADHE","AH",["AB","DE","AH","BH","AD"],[["BH","BH is the line itself. Its projection lies in the face ADHE: drop a perpendicular from each end."],["AB","AB is a perpendicular from the line to the face ADHE. It joins the line to its projection; the projection is the line in the plane, AH."],["DE","DE lies in the face ADHE, but it does not join the feet of the perpendiculars from B and H."],["AD","AD lies in the face ADHE, but a perpendicular from the far end of BH lands at the other end of AH, not at the end of AD."]],13,9,8]];
/* Design: name the projection of a line onto a plane, then its length. Distractor order in each entry: the line itself, a perpendicular, the other diagonal of the plane, an edge. Every wrong option has its own feedback. Source: adapted from SMP GCSE Higher 2, Chapter 34, A3 (which plane contains the line), turned round. */
ix: 1+rand(10); PP: plist[ix];
lin: PP[1]; pl: PP[2]; prj: PP[3]; DF: PP[5];
ll: PP[6]; ww: PP[7]; hh: PP[8];
LS: "ABCDEFGH"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[0,0,hh],[ll,0,hh],[ll,ww,hh],[0,ww,hh]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
opts: makelist([o, is(o = prj), o], o, PP[4]);
o1: DF[1][1]; o2: DF[2][1]; o3: DF[3][1]; o4: DF[4][1];
cmp: sublist(map(abs, vv(prj)), lambda([t], is(t > 0)));
two: is(length(cmp) = 2); ca: cmp[1]; cb: if two then cmp[2] else 0;
S1: sq(prj); tl: dst(prj); tlr: r2(tl); tla: tl+0.02; tlg: tl+0.5;
dl1: dst(lin); dl2: if two then cmp[1]+cmp[2] else NA; dl3: if two then S1 else NB; dl4: dst(o2);
